import{f as s,c as i,o as t,aq as a}from"./chunks/framework.D_PxWklb.js";const c=JSON.parse('{"title":"Zertifikate für SSL erstellen","description":"","frontmatter":{},"headers":[],"relativePath":"technik/guides/generate certs for ssl.md","filePath":"technik/guides/generate certs for ssl.md"}'),n={name:"technik/guides/generate certs for ssl.md"};function r(l,e,h,d,k,p){return t(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="zertifikate-fur-ssl-erstellen" tabindex="-1">Zertifikate für SSL erstellen <a class="header-anchor" href="#zertifikate-fur-ssl-erstellen" aria-label="Permalink to &quot;Zertifikate für SSL erstellen&quot;">​</a></h1><h2 id="kontext" tabindex="-1">Kontext <a class="header-anchor" href="#kontext" aria-label="Permalink to &quot;Kontext&quot;">​</a></h2><p>Der Zugriff auf das Wahllokalsystem soll über eine gesicherte Verbindung erfolgen (siehe <a href="/Wahllokalsystem/technik/systemspecification/#architektur-der-laufzeitumgebung">Architektur der Laufzeitumgebung</a>). Bei der Entwicklung kommen Reverse-Proxies zum Einsatz, die eine HTTPS-Verbindung verlangen, aber mit den Services dann via HTTP kommunizieren. Für die HTTPS-Verbindungen müssen die Reverse-Proxies entsprechend Zertifikate bereitstellen.</p><p>Die Verwendung der Zertifikate ist in der Konfiguration des Nginx (<code>nginx.conf</code>) zu finden.</p><h2 id="zertifikat-erstellen" tabindex="-1">Zertifikat erstellen <a class="header-anchor" href="#zertifikat-erstellen" aria-label="Permalink to &quot;Zertifikat erstellen&quot;">​</a></h2><p>Public und Private Key werden mit OpenSSL erzeugt:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Zertifikat für ca. 10 Jahre erstellen</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> req</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -x509</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -nodes</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -days</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3650</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -newkey</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rsa:2048</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -keyout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> key.pem</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cert.pem</span></span></code></pre></div><p>Dabei werden diverse Parameter abgefragt. Folgende Werte sollten dabei verwendet werden:</p><ul><li>country: <code>DE</code></li><li>province: <code>Bavaria</code></li><li>city: <code>Munich</code></li><li>organization: <code>WLS</code></li><li>organizational unit: <code>IT@m</code></li><li>common name: Hier muss der FQDN des Reverse-Proxies verwendet werden (siehe <code>server_name</code> in <code>nginx.conf</code>).</li></ul><h2 id="truststore-erstellen" tabindex="-1">Truststore erstellen <a class="header-anchor" href="#truststore-erstellen" aria-label="Permalink to &quot;Truststore erstellen&quot;">​</a></h2><p>Services, die eine HTTPS-Verbindung aufbauen müssen, benötigen entsprechend einen Truststore. Dieser wird wie folgt erstellt:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Konvertierung des Public Key</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> x509</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -outform</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> der</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -in</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cert.pem</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cert.der</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Erstellung des Truststore</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">keytool</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -importcert</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -alias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wls-auth-service</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cert.der</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -keystore</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> truststore.p12</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -storetype</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PKCS12</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -storepass</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> changeit</span></span></code></pre></div><h2 id="truststore-einbinden" tabindex="-1">Truststore einbinden <a class="header-anchor" href="#truststore-einbinden" aria-label="Permalink to &quot;Truststore einbinden&quot;">​</a></h2><p>Die Einbindung des Truststore in einen Service erfolgt durch folgende VM-Options:</p><ul><li><code>-Djavax.net.ssl.trustStore=./../stack/reverse-proxy-auth-service/ssl/truststore.p12 -Djavax.net.ssl.trustStorePassword=changeit -Djavax.net.ssl.trustStoreType=PKCS12</code></li></ul>`,15)])])}const u=s(n,[["render",r]]);export{c as __pageData,u as default};
